describe('Login Functionality', () => {
  it('should not change the URL when incorrect credentials are entered', () => {
    cy.visit('https://www.saucedemo.com/login');
    cy.get('input[name="user_name"]').type('locked_out_user');
    cy.get('input[name="password"]').type('secret_sauce');
    cy.get('input[name="remember"]').click();
    cy.get('input[name="submit"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/login');
  });

  it('should display the error message when incorrect credentials are entered', () => {
    cy.visit('https://www.saucedemo.com/login');
    cy.get('input[name="user_name"]').type('locked_out_user');
    cy.get('input[name="password"]').type('secret_sauce');
    cy.get('input[name="remember"]').click();
    cy.get('input[name="submit"]').click();
    cy.get('[data-test="error"]').should('be.visible');
    cy.get('[data-test="error"]').contains('Sorry, this user has been locked out').should('be.visible');
  });
});
